// Package pool provides a typed sync.Pool for objects that can reset their
// state, for example structs with a Reset method generated by cmd/reset.
package pool

import "sync"

// Resetter is an object that can reset its state to the initial one.
type Resetter interface {
	Reset()
}

// Pool keeps objects of type T for reuse. It is safe for concurrent use.
type Pool[T Resetter] struct {
	pool sync.Pool
}

// New returns a pool that creates objects with newFn when it is empty.
func New[T Resetter](newFn func() T) *Pool[T] {
	p := &Pool[T]{}
	p.pool.New = func() any {
		return newFn()
	}
	return p
}

// Get returns an object from the pool or a new one if the pool is empty.
func (p *Pool[T]) Get() T {
	return p.pool.Get().(T)
}

// Put resets x and puts it back to the pool. x must not be used after Put.
func (p *Pool[T]) Put(x T) {
	x.Reset()
	p.pool.Put(x)
}
